-- 192: Family Circle invite links (QR codes) and join requests.
--
-- Until now a Family Circle could only invite a named @username
-- (p2p_family_invitations, shepherd → invitee, invitee accepts). This adds a
-- shareable link a Shepherd or Co-Shepherd can show as a QR code. Because
-- Family Circles include teens and children, a link never adds anyone by
-- itself: scanning it lets a signed-in person ASK to join, and a Shepherd or
-- Co-Shepherd approves or declines (p2p_family_join_requests).
--
-- Links: random 192-bit tokens (generated by the API); only a SHA-256 hash
-- is stored, so the table can't be used to rebuild a link. Each link has a
-- role (adult/teen/child — never co_shepherd), an expiry, a use limit and
-- can be revoked.
--
-- Access: the API (service role) only. RLS is on with NO client policies and
-- client grants are revoked, so the app can't read tokens, links or other
-- people's requests directly; every check (manager role, expiry, revocation,
-- use limit, membership) happens server-side in routes/family.ts.
--
-- Additive and re-runnable: new tables only; nothing existing is changed.

create table if not exists public.p2p_family_invite_links (
  id          uuid primary key default gen_random_uuid(),
  family_id   uuid not null references public.p2p_families(id) on delete cascade,
  created_by  uuid not null references auth.users(id) on delete cascade,
  token_hash  text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  role        text not null default 'adult' check (role in ('adult', 'teen', 'child')),
  expires_at  timestamptz not null,
  revoked_at  timestamptz,
  max_uses    integer not null default 25 check (max_uses between 1 and 200),
  use_count   integer not null default 0 check (use_count >= 0),
  created_at  timestamptz not null default now()
);
create index if not exists idx_p2p_family_invite_links_family on public.p2p_family_invite_links (family_id, created_at desc);

create table if not exists public.p2p_family_join_requests (
  id            uuid primary key default gen_random_uuid(),
  family_id     uuid not null references public.p2p_families(id) on delete cascade,
  user_id       uuid not null references auth.users(id) on delete cascade,
  link_id       uuid references public.p2p_family_invite_links(id) on delete set null,
  role          text not null default 'adult' check (role in ('adult', 'teen', 'child')),
  status        text not null default 'pending' check (status in ('pending', 'approved', 'declined')),
  requested_at  timestamptz not null default now(),
  responded_at  timestamptz,
  responded_by  uuid references auth.users(id) on delete set null,
  unique (family_id, user_id)
);
create index if not exists idx_p2p_family_join_requests_family on public.p2p_family_join_requests (family_id, status);

alter table public.p2p_family_invite_links enable row level security;
alter table public.p2p_family_join_requests enable row level security;
revoke all on public.p2p_family_invite_links from anon, authenticated;
revoke all on public.p2p_family_join_requests from anon, authenticated;
grant select, insert, update, delete on public.p2p_family_invite_links to service_role;
grant select, insert, update, delete on public.p2p_family_join_requests to service_role;
